const CartContext = createContext();
const useCart = () => useContext(CartContext);

const injectStyles = () => {
  if (document.getElementById("hj-shop-styles")) return;
  const style = document.createElement("style");
  style.id = "hj-shop-styles";
  style.textContent = `
    @import url('https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;500;600;700;900&family=Noto+Sans+TC:wght@300;400;500;700&display=swap');
    :root {
      --ink: #1a1612; --parchment: #f7f3ec; --cream: #faf8f4;
      --gold: #b8956a; --gold-light: #d4b896; --gold-dark: #8a6d4a;
      --forest: #2d3a2d; --forest-light: #3d4f3d; --sage: #8b9a7e;
      --mist: #e8e2d8; --warm-gray: #a09688; --error: #c44b4b; --success: #4a7c59;
    }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Noto Sans TC', sans-serif; background: var(--cream); color: var(--ink); overflow-x: hidden; }
    @keyframes fadeUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
    @keyframes slideDown { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
    @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
    @keyframes kenBurns { from { transform: scale(1); } to { transform: scale(1.06); } }
    .serif { font-family: 'Noto Serif TC', serif; }
    .calligraphy { font-family: 'Noto Serif TC', serif; font-weight: 900; text-shadow: 1px 1px 0px rgba(0,0,0,0.08), -0.5px 0px 0px rgba(0,0,0,0.05); font-feature-settings: 'liga' 1; -webkit-font-smoothing: antialiased; }
    ::selection { background: var(--gold-light); color: var(--ink); }
    input:focus, textarea:focus { outline: 2px solid var(--gold); outline-offset: 2px; }
    ::-webkit-scrollbar { width: 6px; }
    ::-webkit-scrollbar-track { background: var(--parchment); }
    ::-webkit-scrollbar-thumb { background: var(--gold-light); border-radius: 3px; }
    .photo-zoom { transition: transform 0.7s cubic-bezier(0.23,1,0.32,1); }
    .photo-zoom:hover { transform: scale(1.04); }
  `;
  document.head.appendChild(style);
};

export default function App() {
  const [page, setPage] = useState("home");
  const [cart, setCart] = useState([]);
  const [products, setProducts] = useState(() => {
    try { const c = JSON.parse(localStorage.getItem("hj_products") || "null"); if (Array.isArray(c) && c.length) return c; } catch (e) {}
    return [];
  });
  const [productsLoaded, setProductsLoaded] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [notification, setNotification] = useState(null);

  useEffect(() => { injectStyles(); loadProducts(); }, []);

  const loadProducts = async () => {
    const data = await supaFetch("products", { query: "?order=id.asc" });
    if (data && data.length > 0) {
      setProducts(data);
      try { localStorage.setItem("hj_products", JSON.stringify(data)); } catch (e) {}
    } else {
      setProducts((prev) => (prev.length ? prev : DEFAULT_PRODUCTS));
    }
    setProductsLoaded(true);
  };

  const showNotification = (msg, type = "success") => {
    setNotification({ msg, type });
    setTimeout(() => setNotification(null), 2500);
  };

  const addToCart = (product, qty = 1) => {
    const key = `${product.id}-${product.weight}`;
    setCart((prev) => {
      const existing = prev.find((i) => i.key === key);
      if (existing) return prev.map((i) => i.key === key ? { ...i, qty: i.qty + qty } : i);
      return [...prev, { ...product, qty, key }];
    });
    showNotification(`已加入 ${product.name}`);
  };

  const removeFromCart = (key) => setCart((prev) => prev.filter((i) => i.key !== key));
  const updateQty = (key, qty) => { if (qty <= 0) return removeFromCart(key); setCart((prev) => prev.map((i) => i.key === key ? { ...i, qty } : i)); };
  const cartTotal = cart.reduce((s, i) => s + i.price * i.qty, 0);
  const cartCount = cart.reduce((s, i) => s + i.qty, 0);

  const navigate = (p, product = null) => {
    setSelectedProduct(product);
    setPage(p);
    // window.scrollTo 在 iframe 環境無效，需直接重設 DOM scroll
    window.scrollTo(0, 0);
    document.documentElement.scrollTop = 0;
    document.body.scrollTop = 0;
  };

  return (
    <CartContext.Provider value={{ cart, addToCart, removeFromCart, updateQty, cartTotal, cartCount }}>
      <div style={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
        <Header page={page} navigate={navigate} cartCount={cartCount} />
        {notification && <Notification {...notification} />}
        <main style={{ flex: 1 }}>
          {page === "home"     && <HomePage navigate={navigate} products={products} loaded={productsLoaded} />}
          {page === "products" && <ProductsPage products={products} navigate={navigate} loaded={productsLoaded} />}
          {page === "detail"   && selectedProduct && <ProductDetail product={selectedProduct} navigate={navigate} />}
          {page === "cart"     && <CartPage navigate={navigate} />}
          {page === "checkout" && <CheckoutPage navigate={navigate} showNotification={showNotification} cart={cart} setCart={setCart} />}
        </main>
        <Footer navigate={navigate} />
      </div>
    </CartContext.Provider>
  );
}

function Notification({ msg, type }) {
  return (
    <div style={{
      position: "fixed", top: 90, right: 24, zIndex: 9999,
      background: type === "success" ? "var(--forest)" : type === "error" ? "var(--error)" : "var(--gold-dark)",
      color: "#fff", padding: "14px 28px", borderRadius: 8,
      fontWeight: 500, fontSize: 14, letterSpacing: 0.5,
      animation: "slideDown 0.4s ease", boxShadow: "0 8px 30px rgba(0,0,0,0.15)",
    }}>{msg}</div>
  );
}

function Header({ page, navigate, cartCount }) {
  const mobile = useIsMobile();
  const navItems = [
    { key: "home",     label: "首頁" },
    { key: "products", label: "茶品" },
    { key: "cart",     label: `購物車${cartCount > 0 ? ` (${cartCount})` : ""}` },
  ];
  return (
    <header style={{
      position: "fixed", top: 0, left: 0, right: 0, zIndex: 1000,
      background: "rgba(255,255,255,0.96)", backdropFilter: "blur(12px)",
      borderBottom: "1px solid rgba(184,149,106,0.2)",
      boxShadow: "0 2px 20px rgba(0,0,0,0.06)",
      padding: mobile ? "10px 0" : "12px 0",
    }}>
      <div style={{ maxWidth: 1200, margin: "0 auto", padding: "0 16px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div onClick={() => navigate("home")} style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
          <img src="/logo.jpg" alt="鴻記製茶" style={{ width: mobile ? 36 : 44, height: mobile ? 36 : 44, objectFit: "contain", flexShrink: 0 }} />
          <div>
            <div className="calligraphy" style={{ fontSize: mobile ? 20 : 28, color: "var(--forest)", letterSpacing: mobile ? 3 : 6, lineHeight: 1.2 }}>鴻記製茶</div>
            {!mobile && <div style={{ fontSize: 9, letterSpacing: 4, color: "var(--warm-gray)", textTransform: "uppercase", fontWeight: 500 }}>HONGJI TEA HOUSE</div>}
          </div>
        </div>
        <nav style={{ display: "flex", gap: 4, alignItems: "center" }}>
          {navItems.map((item) => (
            <button key={item.key} onClick={() => navigate(item.key)} style={{
              background: page === item.key ? "#2d3a2d" : "transparent",
              color: page === item.key ? "#fff" : "#2d3a2d",
              border: "none", padding: mobile ? "6px 12px" : "8px 20px", borderRadius: 24,
              fontSize: mobile ? 13 : 14, fontWeight: page === item.key ? 600 : 500, cursor: "pointer",
              fontFamily: "'Noto Sans TC', sans-serif", transition: "all 0.3s ease", letterSpacing: 1, whiteSpace: "nowrap",
            }}
              onMouseEnter={(e) => { if (page !== item.key) e.currentTarget.style.background = "var(--mist)"; }}
              onMouseLeave={(e) => { if (page !== item.key) e.currentTarget.style.background = "transparent"; }}
            >{item.label}</button>
          ))}
        </nav>
      </div>
    </header>
  );
}

